/* The floating Flows menu: each flow to try, with a start link and the inventory entries it touches. */
(function () {
  var W = window.W, e = W.esc;
  W.FLOWS = [
    { t: "1. Nothing is public before approval", r: "REQ-208, 084, 141, 143, 148", role: "visitor", go: "#/profile/sample-energy-group", inv: ["V15", "A04", "V48"], s: ["As a visitor, open the link: 404.", "Switch to Reviewer (top bar), open Review queue, open Sample Energy Group.", "Clear the scan flag, remove the unsourced field, tick the checklist, approve.", "Visit the page again (200) and check the Sitemap preview."] },
    { t: "2. Unpublish, 410 and purge", r: "REQ-091, 209", role: "editor", go: "#/admin/profiles", inv: ["A05", "V12", "A48", "V48"], s: ["Unpublish Sample Media House with a reason.", "Open its public URL: 410 page.", "Check Sitemap preview and the Purge log.", "Restore it: 200 again."] },
    { t: "3. Bulk unpublish by filter, 410 and restore", r: "REQ-193, 209, 242, D-043, D-045", role: "reviewer", go: "#/admin/profiles?type=individual&origin=import", inv: ["A05", "A59", "V03", "V12", "V48", "A48"], s: ["The Profiles list is filtered to imported individuals. Read the match count, then press Unpublish these N\u2026, give a reason and confirm. Verified and Featured imports are included; customer-submitted Sample Person A is not.", "As a visitor open People: those profiles are gone. Open Sample Person B directly: 410. Check Sitemap preview and the Purge log.", "Switch to Editor and open the same list: there is no bulk panel (Reviewer and Administrator only, unless the Administrator grants it; see flow 19). Back as Reviewer, under Recent bulk actions press Restore this batch: the URLs return 200.", "Try Group by Source and Group by Import batch, and the Sources screen (read-only)."] },
    { t: "4. Nominations flag and the nominate journey", r: "REQ-106, 194, 195, 196, 233", role: "visitor", go: "#/nominate", inv: ["V22", "A26", "N01", "N02", "N12", "N03", "N04", "N05", "N10", "N11"], s: ["See the closed state and sign up for the email.", "Switch to Administrator, Feature flag: turn Nominations ON with a reference. It is the only flag.", "Back on Nominate, fill step 1, then open the email outbox and click the single-use verification link (no account).", "Try evidence with a phone number; try nominating Sample Fintech Ltd. for the duplicate warning.", "Submit three times for the rate limit."] },
    { t: "5. Screening and nominee response by signed link", r: "REQ-197, 198, 207, 233", role: "editor", go: "#/admin/nominations", inv: ["A28", "A29", "N06", "N07", "N08", "A22"], s: ["Open NOM-0002: start screening, mark eligible and invite.", "Open the email in the outbox: a single-use link, no account. Accept, Correct or Decline.", "Decline: nominee suppressed and the profile returns 410."] },
    { t: "6. Offline judging: staff enter the scores", r: "REQ-036, 037, 200, 234", role: "editor", go: "#/admin/scores", inv: ["A51", "A52", "A53", "A31", "A32", "V20"], s: ["Open NOM-0004 and enter scores for Sample Judge 2 and 3; save. Judging is offline, so there is no flag.", "Open NOM-0005: Sample Judge 2 has a recorded conflict, so there are no score boxes for that judge.", "In Judging panel and conflicts, record a conflict for another judge: any score they had is removed.", "As Editor, shortlist NOM-0004. Then open Shortlist and winners and press Publish page for NOM-0001 and NOM-0004.", "As a visitor, open Awards, a category with a shortlist, and the nominee page."] },
    { t: "7. Shortlist and winners: the publish step", r: "REQ-038, 198", role: "admin", go: "#/admin/announcements", inv: ["A32", "V21", "V20"], s: ["Mark a nomination Winner (Nominations > finalist).", "Publish its nominee page and then the winners announcement. There is no flag; nothing shows before you publish.", "View Winners as a visitor."] },
    { t: "8. Staff edit a profile directly", r: "REQ-125, 188", role: "editor", go: "#/admin/profiles/b1", inv: ["A06", "A58", "A33"], s: ["Open Sample Agritech Co. and use Edit this profile: change the city, give a reason, save.", "The public page changes at once. Check the revision history card.", "Switch to Administrator, Audit log: the edit is logged with actor and reason. There is no second-approver step."] },
    { t: "9. Lead to counted subscription", r: "REQ-177, 178, 179, 022, 181", role: "visitor", go: "#/subscribe", inv: ["V24", "A13", "A15", "A16", "A02"], s: ["Send the enquiry form.", "Editor: Leads, convert it.", "Administrator: Register, fill every payment field and watch the counting check turn Yes.", "Administrator dashboard: the count rises."] },
    { t: "10. Sponsored label and its end", r: "REQ-155, 182, 116", role: "admin", go: "#/admin/register/arr1", inv: ["A16", "V36", "V09"], s: ["See Sample Fintech Ltd. with the Sponsored label.", "End arrangement arr1: the label disappears; status stays Verified."] },
    { t: "11. Verified cannot be bought", r: "REQ-153, 183, 184", role: "editor", go: "#/admin/profiles/b1", inv: ["A06", "A16"], s: ["Try Set Verified without the checklist: refused.", "As Administrator, confirm a payment for a profile in Register: its status does not change."] },
    { t: "12. Invited customer onboarding by single-use link", r: "REQ-013, 014, 084, 233", role: "visitor", go: "#/invite/demo", inv: ["O23", "O06", "O07", "O09", "O24", "A04"], s: ["Start my profile (no account), fill the form, save a draft, submit.", "Open the same link again: it has expired (single use).", "Switch to Reviewer; approve the profile. It goes public with the Reviewed on label."] },
    { t: "13. Role views: dashboard, left menu and read-only Sources", r: "REQ-083, 235, 239, 240, 243", role: "reviewer", go: "#/admin", inv: ["A02", "A54", "A59", "A05", "O21"], s: ["As Reviewer: the dashboard shows only review and directory tiles, and the left menu has seven items.", "Open Sources: a read-only table (profiles, last import, errors, removals). Press Show these profiles, then Group by Import batch.", "As Reviewer, change the address to #/admin/import or #/admin/inbox: 403.", "Switch to Editor: the dashboard adds support and nominations counts; switch to Administrator: sprint target, revenue per stream and arrangements appear, and Roles and permissions lists every menu."] },
    { t: "14. Correction, removal and report land in the Support inbox", r: "REQ-089, 156, 157, 158, 090", role: "visitor", go: "#/profile/sample-person-c", inv: ["V39", "V40", "V44", "A12", "A06"], s: ["Request removal for Sample Person C. Send a correction for Sample Agritech Co. Report Sample Media House.", "Switch to Editor, Support inbox: the items are typed (Correction, Removal, Report) with a status and a due countdown.", "Removal: Valid, hide + suppress (410 and the suppression list). Correction: Edit the profile and tick the item it resolves."] },
    { t: "15. Enquiry relay, rate limit and staff switch-off", r: "REQ-018, 122, 236", role: "visitor", go: "#/profile/sample-person-a", inv: ["V43", "A12", "A55", "V47"], s: ["Send an enquiry; send three for the rate limit.", "Switch to Editor and open the Support inbox: the enquiry is there, not with an owner.", "Open Profiles, Sample Person A, and switch enquiries off on request. The button disappears on the public page."] },
    { t: "16. Data request and cookies", r: "REQ-059, 062", role: "visitor", go: "#/data-rights", inv: ["V50", "A35", "V46"], s: ["Submit a request; staff close it.", "Change the cookie choice in the footer."] },
    { t: "17. Import with dry run, and taxonomy terms", r: "REQ-009, 092, 147, 237", role: "admin", go: "#/admin/import", inv: ["A20", "A22", "A57"], s: ["Run the dry run on the sample CSV: an error row, a duplicate, a suppressed name and a blocked row for an unknown industry.", "Open Taxonomies > Industries and add Mining, then dry run again: the row is now valid.", "Import valid rows; see them in the queue."] },
    { t: "18. Taxonomies: Editors add terms, Reviewers only assign", r: "REQ-009, D-039", role: "editor", go: "#/admin/taxonomy/cities", inv: ["A57", "A06"], s: ["Add a city under Ghana, for example Kumasi.", "Switch to Reviewer: Taxonomies is not in the menu and the address gives 403.", "As Reviewer open a profile: Assign existing terms offers the existing terms only."] },
    { t: "19. Staff sign-in with two-factor, 403 and the roles matrix", r: "REQ-047, 083, 229, 235, 244", role: "visitor", go: "#/staff/signin", inv: ["A01", "O21", "A34", "A54", "A60", "A05"], s: ["There is no login on the public site. Staff sign in here (wp-admin preview) as Reviewer with code 000000.", "Open Feature flag: 403.", "Switch to Administrator and open Roles and permissions: the matrix and the left menu for Reviewer, Editor and Administrator. Judge is not a role.", "Open Users and capabilities. Grant Sample Editor the bulk_unpublish capability. Switch to Editor, open Profiles filtered to imported individuals (#/admin/profiles?origin=import): the bulk panel now appears. Back as Administrator, revoke it: the panel is gone.", "Grant Sample Reviewer the stories capability: Articles appears in the Reviewer’s menu and the address opens. Revoke it: 403 again. Try users_roles or settings on a non-Administrator: locked (proposed limit, Q72)."] }
  ];
  W.flowsHtml = function () {
    return '<div id="flows" role="dialog" aria-label="Flows menu"><div class="row between"><h2 style="margin:0">Flows to try</h2><button type="button" class="btn alt sm" data-act="flows">Close</button></div><p class="small muted">Each flow switches the role for you and opens the first screen. Inventory IDs link to the screen list.</p><ol>' + W.FLOWS.map(function (f, i) {
      return "<li><strong>" + e(f.t) + '</strong> <span class="muted small">' + e(f.r) + '</span><ul class="small" style="padding-left:1.1rem;margin:4px 0">' + f.s.map(function (s) { return "<li>" + e(s) + "</li>"; }).join("") + '</ul><button type="button" class="btn sm" data-act="flowGo" data-arg="' + i + '">Start</button> <span class="small">' + f.inv.map(function (id) { return '<a href="#/inventory/' + e(id) + '">' + e(id) + "</a>"; }).join(" ") + "</span></li>";
    }).join("") + "</ol></div>";
  };
  W.act.flowGo = function (i) { var f = W.FLOWS[Number(i)]; W.S.role = f.role; W.ui.flows = false; W.save(); if (location.hash === f.go) W.render(); else location.hash = f.go; };
})();
